  async function establishRestrictedAccount(cfg,u){
    const email=await loginEmail(u.name,cfg.projectId),pw=await loginPassword(u.name,u.pin,cfg.projectId);let sec=null,uid='';
    try{
      sec=await secondary(cfg,u.id||'user');
      const candidates=[];
      if(u.cloudUid&&u.cloudNameSnapshot&&u.cloudPinSnapshot)candidates.push([await loginEmail(u.cloudNameSnapshot,cfg.projectId),await loginPassword(u.cloudNameSnapshot,u.cloudPinSnapshot,cfg.projectId)]);
      candidates.push([email,pw]);
      let cred=null;
      for(const [em,pass] of candidates){try{cred=await sec.auth.signInWithEmailAndPassword(em,pass);break}catch(e){}}
      if(cred){uid=cred.user.uid;if(cred.user.email!==email)await cred.user.updateEmail(email);try{await cred.user.updatePassword(pw)}catch(e){}}
      else{
        try{cred=await sec.auth.createUserWithEmailAndPassword(email,pw);uid=cred.user.uid}
        catch(e){if(e.code==='auth/email-already-in-use'){cred=await sec.auth.signInWithEmailAndPassword(email,pw);uid=cred.user.uid}else throw e}
      }
      return {uid,email,sec};
    }catch(e){if(sec){try{await sec.auth.signOut()}catch(_){ }try{await sec.app.delete()}catch(_){ }}throw e}
  }
  async function syncOneNow(id){
    const u=S.viewerUsers.find(x=>x.id===id);if(!u)throw Error('User not found');
    const {cfg,auth,db}=await ready();if(!auth.currentUser)throw Error('Owner must sign in to Firebase first in Settings.');const owner=auth.currentUser.uid;await ensureOwner(db,owner);
    const oldUid=u.cloudUid||'',acct=await establishRestrictedAccount(cfg,u),uid=acct.uid,email=acct.email,sec=acct.sec;
    try{if(oldUid&&oldUid!==uid){const oldProfile=db.collection('accessProfiles').doc(oldUid);await oldProfile.set({active:false,revokedAt:firebase.firestore.FieldValue.serverTimestamp()},{merge:true});await deletePayload(db,oldUid);await oldProfile.delete()}
      const payload=payloadFor(u),active=u.active!==false,profile={ownerUid:owner,username:u.name,usernameKey:norm(u.name),role:u.role||'customer',active,accessVersion:payload.accessVersion,offlineValidUntil:payload.offlineValidUntil,expiresAt:payload.accessExpiresAt?firebase.firestore.Timestamp.fromMillis(payload.accessExpiresAt):null,allowedPriceBookIds:u.allowedPriceBookIds||[],allowedCatalogFileIds:u.allowedCatalogFileIds||[],updatedAt:firebase.firestore.FieldValue.serverTimestamp()};
      if(active){await writePayload(db,uid,payload);await db.collection('accessProfiles').doc(uid).set(profile,{merge:true})}
      else{await db.collection('accessProfiles').doc(uid).set(profile,{merge:true});await deletePayload(db,uid)}
      Object.assign(u,{cloudUid:uid,cloudEmail:email,cloudPinSnapshot:u.pin,cloudNameSnapshot:u.name,cloudSyncedAt:Date.now(),cloudAccessVersion:payload.accessVersion});publishSuppress=true;try{save()}finally{publishSuppress=false}return u;
    }finally{try{await sec.auth.signOut()}catch(e){}try{await sec.app.delete()}catch(e){}}
  }
  function syncOne(id){const run=()=>syncOneNow(id);restrictedSyncQueue=restrictedSyncQueue.then(run,run);return restrictedSyncQueue}
  async function revokeUser(u,{deleteAuth=true}={}){
    if(!u)return true;const oldName=u.cloudNameSnapshot||u.name;
    try{
      if(u.cloudUid){
        const {cfg,auth,db}=await ready();
        if(!auth.currentUser)throw Error('Owner must be signed in to Firebase before this cloud login can be removed safely.');
        await ensureOwner(db,auth.currentUser.uid);
        const pref=db.collection('accessProfiles').doc(u.cloudUid);
        await pref.set({active:false,revokedAt:firebase.firestore.FieldValue.serverTimestamp()},{merge:true});
        await deletePayload(db,u.cloudUid);
        await pref.delete();
        if(deleteAuth){let sec=null;try{sec=await secondary(cfg,'revoke');const names=[[u.cloudNameSnapshot||u.name,u.cloudPinSnapshot||u.pin],[u.name,u.pin]];let cred=null;for(const [nm,pn] of names){try{cred=await sec.auth.signInWithEmailAndPassword(await loginEmail(nm,cfg.projectId),await loginPassword(nm,pn,cfg.projectId));break}catch(e){}}if(cred)await cred.user.delete()}catch(e){}finally{if(sec){try{await sec.auth.signOut()}catch(_){}try{await sec.app.delete()}catch(_){}}}}
      }
      try{localStorage.removeItem(CACHE_PREFIX+norm(u.name));localStorage.removeItem(CACHE_PREFIX+norm(oldName))}catch(e){}
      return true;
    }catch(e){throw Error('Cloud access could not be revoked, so the local user was kept. '+(e.message||''))}
  }
  window.revokeViewerUser46=async id=>{const u=S.viewerUsers.find(x=>x.id===id);if(!u)return false;await revokeUser(u);return true};
  window.syncOneUser46=async id=>{try{const u=await syncOne(id);toast('Firebase access updated for '+u.name);render()}catch(e){toast(e.message||'Could not sync user')}};
  window.syncAllUsers46=async()=>{try{if(!(S.viewerUsers||[]).length)return toast('Create a restricted user first');for(const u of S.viewerUsers)if(u.active!==false||u.cloudUid)await syncOne(u.id);toast('Published restricted users securely');render()}catch(e){toast(e.message||'Could not publish users')}};
  window.initSecureAccess46=async()=>{try{const {auth,db}=await ready();if(!auth.currentUser)return toast('Sign in as owner in Firebase Settings first');await ensureOwner(db,auth.currentUser.uid);toast('Secure access initialized for this owner');render()}catch(e){toast(e.message)}};

